4function Header({ query, onQueryChange }) {
5  const { theme, toggleTheme } = useTheme()
6
7  const searchRef = useRef(null);
8
9  useEffect(function () {
10    searchRef.current.focus();
11  }, []);
12
13  function handleChange(e) {
14    onQueryChange(e.target.value);
15  }
16
17  function handleClear() {
18    onQueryChange("");
19    searchRef.current.focus();
20  }
21
22  return (
23    <header className="header">
24      <button className="btn btn-secondary theme-toggle" onClick={toggleTheme}>
25        {theme === 'light' ? 'Dark mode' : 'Light mode'}
26      </button>
27      <h2 className="title-primary">My Daily Journal</h2>
28      <p className="subtitle">Capture your thoughts, one day at a time.</p>
29      <div className="header-search">
30        <input
31          ref={searchRef}
32          className="search-input"
33          type="text"
34          placeholder="Search entries..."
35          value={query}
36          onChange={handleChange}
37        />
38        {query && (
39          <button className="btn-clear" onClick={handleClear}>Clear</button>
40        )}
41      </div>
42    </header>
43  );
44}
